using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Returns the current server environment name")]
    public static string GetEnvironment(IHostEnvironment env)
        => $"Running in: {env.EnvironmentName}";

    [McpServerTool, Description("Echoes a message back to the caller")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer.Tools;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns current application configuration data",
        MimeType = "application/json")]
    public static string GetAppSettings(IConfiguration configuration)
    {
        var settings = new Dictionary<string, string?>
        {
            ["ApplicationName"] = configuration["ApplicationName"] ?? "McpHttpServer",
            ["Version"] = configuration["Version"] ?? "1.0.0",
            ["MaxConnections"] = configuration["MaxConnections"] ?? "100",
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{key}",
        Name = "App Setting by Key",
        Description = "Returns a specific configuration value by key",
        MimeType = "text/plain")]
    public static string GetSettingByKey(
        IConfiguration configuration,
        [Description("The configuration key to look up")] string key)
    {
        return configuration[key] ?? $"No value found for key '{key}'";
    }
}

